CREATE TABLE `ad_campaigns` (
  `seller_id` char(36) NOT NULL,
  `name` varchar(80) NOT NULL,
  `status` varchar(10) NOT NULL,
  `placements` json NOT NULL,
  `keywords` json NOT NULL,
  `bid_paise` bigint NOT NULL,
  `daily_budget_paise` bigint NOT NULL,
  `total_budget_paise` bigint DEFAULT NULL,
  `starts_at` datetime(6) NOT NULL,
  `ends_at` datetime(6) DEFAULT NULL,
  `spend_paise` bigint NOT NULL,
  `note` varchar(300) NOT NULL,
  `id` char(36) NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT (utc_timestamp(6)),
  `updated_at` datetime(6) NOT NULL DEFAULT (utc_timestamp(6)),
  PRIMARY KEY (`id`),
  KEY `ix_ad_campaigns_seller_id` (`seller_id`),
  KEY `ix_ad_campaigns_status` (`status`),
  CONSTRAINT `fk_ad_campaigns_seller_id_sellers` FOREIGN KEY (`seller_id`) REFERENCES `sellers` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_ad_campaigns_money` CHECK (((`bid_paise` > 0) and (`daily_budget_paise` > 0))),
  CONSTRAINT `ck_ad_campaigns_status` CHECK ((`status` in (_utf8mb4'pending',_utf8mb4'active',_utf8mb4'paused',_utf8mb4'rejected',_utf8mb4'ended')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
