CREATE TABLE `delivery_assignments` (
  `order_id` char(36) NOT NULL,
  `sub_order_id` char(36) NOT NULL,
  `delivery_boy_id` char(36) NOT NULL,
  `assigned_by` char(36) DEFAULT NULL,
  `mode` varchar(6) NOT NULL,
  `kind` varchar(8) NOT NULL DEFAULT 'delivery',
  `return_id` char(36) DEFAULT NULL,
  `status` varchar(10) NOT NULL,
  `reject_reason` varchar(200) NOT NULL,
  `assigned_at` datetime(6) NOT NULL,
  `expires_at` datetime(6) DEFAULT NULL,
  `accepted_at` datetime(6) DEFAULT NULL,
  `at_store_at` datetime(6) DEFAULT NULL,
  `picked_at` datetime(6) DEFAULT NULL,
  `on_the_way_at` datetime(6) DEFAULT NULL,
  `reached_at` datetime(6) DEFAULT NULL,
  `delivered_at` datetime(6) DEFAULT NULL,
  `ended_at` datetime(6) DEFAULT NULL,
  `status_at` datetime(6) NOT NULL,
  `stuck_alerted_at` datetime(6) DEFAULT NULL,
  `cod_amount` bigint NOT NULL,
  `cod_collected` bigint NOT NULL,
  `cod_method` varchar(6) NOT NULL,
  `proof_photo` varchar(300) NOT NULL,
