  `picked_lng` decimal(9,6) DEFAULT NULL,
  `drop_lat` decimal(9,6) DEFAULT NULL,
  `drop_lng` decimal(9,6) DEFAULT NULL,
  `distance_km` decimal(7,2) DEFAULT NULL,
  `fee_paise` bigint NOT NULL,
  `tip_paise` bigint NOT NULL DEFAULT '0',
  `bonus_paise` bigint NOT NULL DEFAULT '0',
  `payout_id` char(36) DEFAULT NULL,
  `fail_reason` varchar(200) NOT NULL,
  `rating` smallint DEFAULT NULL,
  `rating_comment` text NOT NULL,
  `rated_at` datetime(6) DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `id` char(36) NOT NULL,
  `active_sub_order_id` char(36) GENERATED ALWAYS AS ((case when (`status` in (_utf8mb4'offered',_utf8mb4'accepted',_utf8mb4'at_store',_utf8mb4'picked',_utf8mb4'on_the_way',_utf8mb4'reached')) then `sub_order_id` end)) VIRTUAL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_delivery_assignments_active` (`active_sub_order_id`),
  KEY `fk_delivery_assignments_assigned_by_users` (`assigned_by`),
  KEY `ix_delivery_assignments_boy_status` (`delivery_boy_id`,`status`),
  KEY `ix_delivery_assignments_delivery_boy_id` (`delivery_boy_id`),
  KEY `ix_delivery_assignments_order_id` (`order_id`),
  KEY `ix_delivery_assignments_payout_id` (`payout_id`),
  KEY `ix_delivery_assignments_return_id` (`return_id`),
  KEY `ix_delivery_assignments_status` (`status`),
  KEY `ix_delivery_assignments_sub_order_id` (`sub_order_id`),
  CONSTRAINT `fk_delivery_assignments_assigned_by_users` FOREIGN KEY (`assigned_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_delivery_assignments_delivery_boy_id_delivery_boys` FOREIGN KEY (`delivery_boy_id`) REFERENCES `delivery_boys` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `fk_delivery_assignments_order_id_orders` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_delivery_assignments_payout_id_delivery_payouts` FOREIGN KEY (`payout_id`) REFERENCES `delivery_payouts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_delivery_assignments_return_id_return_requests` FOREIGN KEY (`return_id`) REFERENCES `return_requests` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_delivery_assignments_sub_order_id_sub_orders` FOREIGN KEY (`sub_order_id`) REFERENCES `sub_orders` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_delivery_assignments_kind` CHECK ((`kind` in (_utf8mb4'delivery',_utf8mb4'return',_utf8mb4'pickup'))),
  CONSTRAINT `ck_delivery_assignments_mode` CHECK ((`mode` in (_utf8mb4'manual',_utf8mb4'auto'))),
  CONSTRAINT `ck_delivery_assignments_money` CHECK (((`cod_collected` >= 0) and (`cod_amount` >= 0) and (`fee_paise` >= 0) and (`bonus_paise` >= 0))),
  CONSTRAINT `ck_delivery_assignments_rating` CHECK (((`rating` is null) or (`rating` between 1 and 5))),
  CONSTRAINT `ck_delivery_assignments_status` CHECK ((`status` in (_utf8mb4'offered',_utf8mb4'accepted',_utf8mb4'at_store',_utf8mb4'picked',_utf8mb4'on_the_way',_utf8mb4'reached',_utf8mb4'delivered',_utf8mb4'rejected',_utf8mb4'expired',_utf8mb4'cancelled',_utf8mb4'failed')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
