CREATE TABLE `notifications` (
  `user_id` char(36) DEFAULT NULL,
  `event` varchar(40) NOT NULL,
  `channel` varchar(10) NOT NULL,
  `recipient` varchar(254) NOT NULL,
  `subject` varchar(200) NOT NULL,
  `body` text NOT NULL,
  `link` varchar(300) NOT NULL,
  `variables` json NOT NULL,
  `status` varchar(10) NOT NULL,
  `attempts` int NOT NULL,
  `error` varchar(500) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `sent_at` datetime(6) DEFAULT NULL,
  `read_at` datetime(6) DEFAULT NULL,
  `id` char(36) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_notifications_created_at` (`created_at`),
  KEY `ix_notifications_status` (`status`),
  KEY `ix_notifications_user_id` (`user_id`),
  CONSTRAINT `fk_notifications_user_id_users` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_notifications_status` CHECK ((`status` in (_utf8mb4'pending',_utf8mb4'sent',_utf8mb4'failed',_utf8mb4'skipped')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `notifications` WRITE;
