CREATE TABLE `order_status_logs` (
  `order_id` char(36) NOT NULL,
  `sub_order_id` char(36) DEFAULT NULL,
  `assignment_id` char(36) DEFAULT NULL,
  `status` varchar(20) NOT NULL,
