  CONSTRAINT `ck_payouts_amount` CHECK ((`amount` > 0)),
  CONSTRAINT `ck_payouts_status` CHECK ((`status` in (_utf8mb4'pending',_utf8mb4'processing',_utf8mb4'paid',_utf8mb4'failed',_utf8mb4'cancelled')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
