UNLOCK TABLES;
DROP TABLE IF EXISTS `sellers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sellers` (
  `user_id` char(36) NOT NULL,
  `status` varchar(12) NOT NULL,
  `display_name` varchar(80) NOT NULL,
  `slug` varchar(90) NOT NULL,
  `description` text NOT NULL,
  `legal_name` varchar(160) NOT NULL,
  `business_type` varchar(20) NOT NULL,
  `gstin` varchar(15) DEFAULT NULL,
  `pan_enc` text,
  `pan_last4` varchar(4) NOT NULL,
  `contact_email` varchar(254) NOT NULL,
  `contact_phone` varchar(15) NOT NULL,
  `pickup_line1` varchar(200) NOT NULL,
  `pickup_line2` varchar(200) NOT NULL,
  `pickup_city` varchar(80) NOT NULL,
  `pickup_state_code` varchar(2) NOT NULL,
  `pickup_pincode` varchar(6) NOT NULL,
  `bank_holder_name` varchar(120) NOT NULL,
  `bank_account_enc` text,
  `bank_account_last4` varchar(4) NOT NULL,
  `bank_ifsc` varchar(11) NOT NULL,
  `grievance_name` varchar(120) NOT NULL,
  `grievance_email` varchar(254) NOT NULL,
  `grievance_phone` varchar(15) NOT NULL,
  `commission_bps_override` int DEFAULT NULL,
  `rejection_reason` text NOT NULL,
  `submitted_at` datetime(6) DEFAULT NULL,
  `approved_at` datetime(6) DEFAULT NULL,
  `razorpay_account_id` varchar(40) NOT NULL,
  `dispatch_days` int NOT NULL DEFAULT '2',
  `dispatch_cutoff` varchar(5) NOT NULL DEFAULT '',
  `holiday_mode` tinyint(1) NOT NULL DEFAULT '0',
  `invoice_prefix` varchar(5) NOT NULL DEFAULT '',
  `payout_contact_id` varchar(40) NOT NULL DEFAULT '',
  `payout_fund_account_id` varchar(40) NOT NULL DEFAULT '',
  `rating_avg` decimal(3,2) NOT NULL DEFAULT '0.00',
  `rating_count` int NOT NULL DEFAULT '0',
  `id` char(36) NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT (utc_timestamp(6)),
  `updated_at` datetime(6) NOT NULL DEFAULT (utc_timestamp(6)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_sellers_user_id` (`user_id`),
  UNIQUE KEY `uq_sellers_slug` (`slug`),
  UNIQUE KEY `uq_sellers_gstin` (`gstin`),
  KEY `ix_sellers_status` (`status`),
  CONSTRAINT `fk_sellers_user_id_users` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ck_sellers_business_type` CHECK ((`business_type` in (_utf8mb4'individual',_utf8mb4'proprietorship',_utf8mb4'partnership',_utf8mb4'llp',_utf8mb4'private_limited',_utf8mb4'public_limited'))),
  CONSTRAINT `ck_sellers_commission` CHECK (((`commission_bps_override` is null) or (`commission_bps_override` between 0 and 5000))),
  CONSTRAINT `ck_sellers_dispatch_days` CHECK ((`dispatch_days` between 0 and 10)),
  CONSTRAINT `ck_sellers_status` CHECK ((`status` in (_utf8mb4'draft',_utf8mb4'submitted',_utf8mb4'approved',_utf8mb4'rejected',_utf8mb4'suspended')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
