  `updated_at` datetime(6) NOT NULL DEFAULT (utc_timestamp(6)),
  PRIMARY KEY (`id`),
  CONSTRAINT `ck_shop_kb_articles_topic` CHECK ((`topic` in (_utf8mb4'orders',_utf8mb4'delivery',_utf8mb4'payments',_utf8mb4'returns',_utf8mb4'account',_utf8mb4'offers',_utf8mb4'selling',_utf8mb4'other')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
