INSERT INTO `shop_kb_articles` (`title`, `body`, `keywords`, `topic`, `link`, `is_published`, `position`, `uses`, `id`, `created_at`, `updated_at`) VALUES ('Sell on {brand}','Anyone with a GSTIN can sell on {brand}: sign in with your mobile, add your business, PAN and bank details, and list your products once your account is approved. Start from **Become a seller**.','[\"sell\", \"seller\", \"vendor\", \"become a seller\", \"list my products\", \"vikka\", \"விற்க\", \"बेचना\"]','selling','/sell',1,13,0,'0cc5c3ed-8956-4205-bcc1-8310c4ebc749','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Contact customer support','Ask me first: I can check your orders, returns and refunds. If you still need a person, I can open a support request for you; the team acknowledges within 48 hours and you can follow it under **Support**.','[\"contact\", \"customer care\", \"human\", \"agent\", \"talk to someone\", \"call\", \"phone number\", \"support\", \"help\"]','other','/support',1,16,0,'1fa04301-5e96-4365-a0f6-f5c6749bfd84','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Return a product','Every product page shows its return window, which starts on the delivery day. While it is open, open the order and choose **Return items**, pick the items, the reason and (for cash on delivery) the UPI ID for your refund. The seller arranges the pickup. Once the seller receives the item, the refund is issued and a credit note is added to your order.','[\"return\", \"replace\", \"replacement\", \"exchange\", \"send back\", \"return pannanum\", \"திருப்பி\", \"वापस\", \"रिटर्न\"]','returns','/pages/returns-policy',1,6,0,'544a65e5-2f42-4818-aabf-25bb93afb29d','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Invoice and GST bill','A tax invoice is issued by the seller when your package ships. Download it from the order page (**Invoice**). Returns get a credit note on the same page.','[\"invoice\", \"bill\", \"gst bill\", \"receipt\", \"பில்\", \"बिल\"]','orders','/orders',1,12,0,'5b41c1a1-40fc-40c0-9709-e5ef5a92fb15','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Track your order','Open **My orders** and choose the order. Each package ships separately from its seller, so one order can arrive in parts. Once a package ships you see the courier, tracking number and a tracking link there. Expected delivery is shown for every package.','[\"track\", \"tracking\", \"where is my order\", \"order status\", \"not received\", \"enga\", \"eppo varum\", \"varala\", \"எங்கே\", \"ஆர்டர்\", \"कहाँ\", \"ऑर्डर कब\"]','orders','/orders',1,0,0,'62b401f9-188a-4cdc-8419-0529b6ac1501','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Cash on delivery','{cod_text}','[\"cod\", \"cash on delivery\", \"pay on delivery\", \"cash\", \"panam\", \"காசு\", \"नकद\"]','payments','',1,2,0,'68ba1eca-baff-4f09-bb87-b935f1dbbcd7','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Damaged, defective or wrong item','Sorry about that. If the return window is open, start a return from the order and choose **Item arrived damaged**, **Item does not work** or **Received a different item**. If the window has closed or the item is not returnable, raise a request with the order number and photos, and our team will help.','[\"damaged\", \"broken\", \"defective\", \"not working\", \"wrong item\", \"different item\", \"fake\", \"udanjirukku\", \"சேதம்\", \"टूटा\", \"खराब\"]','returns','',1,8,0,'8c33ac90-54a8-43ec-8250-401ff47e8bfa','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Grievance officer','{grievance_text}','[\"grievance\", \"complaint\", \"escalate\", \"consumer\", \"legal\", \"புகார்\", \"शिकायत\"]','account','/help/grievance',1,14,0,'a053649d-b10e-4f98-bf1f-5cc74ced1f2e','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Delivery time and charges','Sellers ship from their own warehouses. Delivery usually takes {transit_same_city} day(s) in the same city, up to {transit_same_state} days within the state and up to {transit_national} days elsewhere in India. The delivery fee is {shipping_fee} per seller, and delivery is free when a seller\'s items in your order reach {free_delivery_amount}. The product page shows the delivery date for your PIN code.','[\"delivery charge\", \"shipping\", \"how many days\", \"delivery time\", \"free delivery\", \"pincode\", \"eththanai naal\", \"டெலிவரி\", \"डिलीवरी\"]','delivery','/pages/shipping-policy',1,1,0,'afd25df2-a8c9-4f7f-84bd-2ee3054fc330','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Cancel an order','You can cancel a package until it ships: open **My orders**, choose the order and press **Cancel this package**, or ask me to do it. Online payments are refunded automatically to the original payment method within 5 to 7 working days. Once a package has shipped it cannot be cancelled; you can return it after delivery if it is returnable.','[\"cancel\", \"cancel order\", \"don\'t want\", \"venaam\", \"cancel pannanum\", \"ரத்து\", \"रद्द\"]','orders','/orders',1,5,0,'b3f97c89-fcf0-41c3-b8e6-f511c460cc2c','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Your data and deleting your account','In **My account** you can download your data, change marketing consent or delete your account. Orders already placed are kept as long as tax law requires.','[\"delete account\", \"privacy\", \"my data\", \"unsubscribe\", \"remove account\"]','account','/account',1,15,0,'c2728bea-8e1a-4d57-8a7f-9361ecd96afe','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('When will I get my refund?','Online payments: refunds go back to the original method and usually show within 5 to 7 working days of being issued (UPI is often faster). Cash on delivery: the refund is sent to the UPI ID you gave with the return. The order page shows each refund and its status.','[\"refund\", \"refund status\", \"money back\", \"refund varala\", \"eppo refund\", \"பணம் திரும்ப\", \"रिफंड\", \"पैसा वापस\"]','returns','',1,7,0,'cd824b1f-b55f-4867-9b60-79158b5ec980','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Sign in and one-time codes (OTP)','We sign you in with your mobile number and a 6-digit code sent by SMS; there is no password. If the code does not arrive, check the number, wait 30 seconds and press **Resend code**. A code works for 5 minutes and only the latest code is valid.','[\"otp\", \"login\", \"sign in\", \"code not received\", \"can\'t login\", \"password\", \"உள்நுழை\", \"लॉगिन\"]','account','/login',1,9,0,'cfbb2f33-0ef6-4436-8fb0-46e7a9069f73','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Payment failed or money deducted','If money left your account but the order still says payment pending, wait 30 minutes: the bank\'s confirmation usually arrives on its own and the order is placed. If the payment is not confirmed, your bank reverses the amount within 5 to 7 working days. If it has not come back after that, raise a request with the order number and we will check it.','[\"payment failed\", \"money deducted\", \"amount debited\", \"paid but\", \"transaction failed\", \"upi failed\", \"panam pochu\", \"பணம்\", \"पैसे कट\"]','payments','',1,4,0,'def927ce-3883-4f14-b080-6a6cbe4857ef','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Change address or phone number','Saved addresses are in **My account**. The address of an order that is already placed cannot be changed; if it has not shipped yet, cancel it and order again with the right address.','[\"address\", \"change address\", \"wrong address\", \"phone number\", \"mobile number\", \"முகவரி\", \"पता\"]','account','/account',1,10,0,'f438dc5d-87fd-481d-be57-935b9bb77409','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Fees on your bill','{fees_text}','[\"fee\", \"fees\", \"extra charge\", \"charges\", \"handling fee\", \"platform fee\", \"small cart\", \"late night\", \"night fee\", \"rain fee\", \"bad weather\", \"surge\", \"why charged\", \"kattanam\", \"extra panam\", \"கட்டணம்\", \"शुल्क\", \"चार्ज\"]','payments','',1,3,0,'fb908abf-9f7c-426e-81c5-d0b41d4567b2','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476'),('Coupons and offers','Available coupons are listed at checkout; one coupon can be used per order and its conditions (minimum amount, first order) are shown with it. Deals on products are shown on the home page and in search with **Sort by discount**.','[\"coupon\", \"offer\", \"discount\", \"promo code\", \"deal\", \"sale\", \"கூப்பன்\", \"ऑफर\"]','offers','',1,11,0,'fd979b71-6ab0-4955-83b1-0dce5c71f603','2026-11-25 06:04:32.470476','2026-11-25 06:04:32.470476');
/*!40000 ALTER TABLE `shop_kb_articles` ENABLE KEYS */;
