CREATE TABLE `support_tickets` (
  `number` varchar(20) NOT NULL,
  `user_id` char(36) NOT NULL,
  `order_id` char(36) DEFAULT NULL,
  `category` varchar(30) NOT NULL,
  `subject` varchar(200) NOT NULL,
  `status` varchar(20) NOT NULL,
  `priority` varchar(8) NOT NULL,
  `assigned_to` char(36) DEFAULT NULL,
  `is_grievance` tinyint(1) NOT NULL,
  `ack_due_at` datetime(6) NOT NULL,
  `resolve_due_at` datetime(6) NOT NULL,
  `acknowledged_at` datetime(6) DEFAULT NULL,
  `resolved_at` datetime(6) DEFAULT NULL,
  `id` char(36) NOT NULL,
  `created_at` datetime(6) NOT NULL DEFAULT (utc_timestamp(6)),
  `updated_at` datetime(6) NOT NULL DEFAULT (utc_timestamp(6)),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_support_tickets_number` (`number`),
  KEY `fk_support_tickets_order_id_orders` (`order_id`),
  KEY `fk_support_tickets_assigned_to_users` (`assigned_to`),
  KEY `ix_support_tickets_status` (`status`),
  KEY `ix_support_tickets_user_id` (`user_id`),
  CONSTRAINT `fk_support_tickets_assigned_to_users` FOREIGN KEY (`assigned_to`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_support_tickets_order_id_orders` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_support_tickets_user_id_users` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `ck_support_tickets_priority` CHECK ((`priority` in (_utf8mb4'low',_utf8mb4'normal',_utf8mb4'high',_utf8mb4'urgent'))),
  CONSTRAINT `ck_support_tickets_status` CHECK ((`status` in (_utf8mb4'open',_utf8mb4'awaiting_customer',_utf8mb4'resolved',_utf8mb4'closed')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
